# workers/smile_corrector.py
"""Smile correction using pre-computed cv2.remap maps."""

from __future__ import annotations

import os
import logging

import cv2
import numpy as np

logger = logging.getLogger("HSI")


class SmileCorrector:
    """Apply smile correction maps generated by PrecisionOpticsGUI.

    Maps from calibration_logic.generate_smile_maps():
        mx: float32 (h, w) — source x for each destination pixel
        my: float32 (h, w) — source y for each destination pixel

    Usage:
        corrector = SmileCorrector(folder="smile_maps/")
        corrector.set_bin(4)
        corrected = corrector.apply(frame)  # cv2.remap per frame
    """

    def __init__(self, folder: str = ""):
        self._folder = folder
        self._current_bin: int = 0
        self._map_x: np.ndarray | None = None
        self._map_y: np.ndarray | None = None
        self._enabled = False

    @property
    def enabled(self) -> bool:
        return self._enabled

    @property
    def current_bin(self) -> int:
        return self._current_bin

    def set_folder(self, folder: str) -> None:
        self._folder = folder
        if self._current_bin > 0:
            self.set_bin(self._current_bin)

    def set_bin(self, bin_value: int) -> bool:
        """Load maps for given bin. Returns True if found."""
        self._current_bin = bin_value
        self._map_x = None
        self._map_y = None
        self._enabled = False

        if not self._folder or not os.path.isdir(self._folder):
            return False

        path_x = os.path.join(self._folder, f"smile_map_x_bin{bin_value}.npy")
        path_y = os.path.join(self._folder, f"smile_map_y_bin{bin_value}.npy")

        if not os.path.exists(path_x) or not os.path.exists(path_y):
            logger.info("Smile maps not found for bin%d in %s", bin_value, self._folder)
            return False

        try:
            self._map_x = np.load(path_x).astype(np.float32)
            self._map_y = np.load(path_y).astype(np.float32)
            self._enabled = True
            logger.info(
                "Smile maps loaded for bin%d: map_x=%s map_y=%s",
                bin_value, self._map_x.shape, self._map_y.shape,
            )
            return True
        except Exception as e:
            logger.warning("Failed to load smile maps for bin%d: %s", bin_value, e)
            return False

    def apply(self, frame: np.ndarray) -> np.ndarray:
        """Apply smile correction via cv2.remap."""
        if not self._enabled:
            return frame

        fh, fw = frame.shape[:2]
        mh, mw = self._map_x.shape[:2]

        if fh != mh or fw != mw:
            logger.warning(
                "Smile map %dx%d != frame %dx%d — skipping remap",
                mw, mh, fw, fh,
            )
            return frame

        try:
            # ★ ตรงกับ remap_image() ใน calibration_logic
            return cv2.remap(
                frame,
                self._map_x,
                self._map_y,
                interpolation=cv2.INTER_CUBIC,
                borderMode=cv2.BORDER_REFLECT_101,
            )
        except Exception as e:
            logger.warning("Smile remap failed: %s", e)
            return frame